import numpy as np

def problem(x: np.ndarray) -> float:
    dim = x.shape[0]
    Q = np.array([[1.0, 0.2], [0.2, 0.5]]) if dim == 2 else np.eye(dim)
    skewed_quadratic = 0.4 * x @ Q @ x
    if dim >= 2:
        rotation_matrix = np.array([[0.707, -0.707], [0.707, 0.707]])
        x_rotated = x[:2] @ rotation_matrix
        gaussian_peak = -0.5 * np.exp(-0.5 * np.sum(x_rotated**2))
    else:
        gaussian_peak = -0.5 * np.exp(-0.5 * x[0]**2) if dim > 0 else -0.5 * np.exp(0)
    if dim >= 1:
        cubic_term = 0.05 * x[0]**3 * np.sin(2 * np.pi * x[0])
    else:
        cubic_term = 0.0
    return skewed_quadratic + gaussian_peak + cubic_term

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function.
    """
    dim = x.shape[0]

    # Scaled and rotated elliptic paraboloid
    Q = np.array([[2.0, 0.5], [0.5, 1.0]]) if dim == 2 else np.eye(dim)
    if dim > 1:
      rotation_matrix = np.array([[np.cos(0.5), -np.sin(0.5)], [np.sin(0.5), np.cos(0.5)]])
      x_rotated = x[:2] @ rotation_matrix
      elliptic_paraboloid = 0.3 * x_rotated @ Q @ x_rotated
    else:
      elliptic_paraboloid = 0.3 * x[0] * Q[0][0] * x[0]


    # Gaussian well with offset
    if dim >= 2:
        gaussian_well = -0.5 * np.exp(-0.4 * np.sum((x[:2] - [2, 1])**2))
    else:
        gaussian_well = -0.5 * np.exp(-0.4 * (x[0] - 2)**2) if dim >=1 else -0.5 * np.exp(-0.4 * 4)

    # Quartic term with sine modulation
    if dim >= 1 :
      quartic_term = 0.2 * x[0]**4 * np.sin(3 * np.pi * x[0])
    else:
      quartic_term = 0.0

    # Exponential decay term with offset on x[1]
    if dim >= 2:
        exponential_decay = 0.4 * np.exp(-0.3 * np.abs(x[1] + 2))
    else:
      exponential_decay = 0.4 if dim>=1 else  0.4

    return elliptic_paraboloid + gaussian_well + quartic_term + exponential_decay

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function designed to test global optimization algorithms.
    """
    dim = x.shape[0]

    # Skewed quartic polynomial (instead of quadratic)
    Q = np.array([[1.0, 0.2], [0.2, 0.5]]) if dim == 2 else np.eye(dim)
    skewed_quartic = 0.1 * np.sum((x @ Q @ x)**2)

    # Sigmoid-modulated cubic term
    if dim >= 1:
        sigmoid = 1 / (1 + np.exp(-x[0]))
        cubic_term = 0.3 * x[0]**3 * sigmoid
    else:
        cubic_term = 0.0

    # Arctangent with Gaussian interaction
    if dim >= 2:
        atan_term = 0.5 * np.arctan(x[0] * x[1]) * np.exp(-0.1 * (x[0]**2 + x[1]**2))
    else:
        atan_term = 0.0

    # Rational Term (variation)
    if dim >= 2:
        rational_term = -0.2 * x[1] / (1 + x[0]**2)
    else:
        rational_term = 0.0

    # Linear term for asymmetry
    if dim >=1:
      linear_term = 0.1* x[0];
    else:
      linear_term = 0.0

    return skewed_quartic + cubic_term + atan_term + rational_term + linear_term

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function designed to test global optimization algorithms.
    """
    dim = x.shape[0]

    # Hyperbolic Paraboloid (Saddle)
    if dim >= 2:
        hyperbolic_paraboloid = 0.3 * (x[0]**2 - x[1]**2)
    else:
        hyperbolic_paraboloid = 0.3 * x[0]**2 if dim > 0 else 0.0

    # Gaussian Well
    if dim >= 2:
        gaussian_well = -0.5 * np.exp(-0.3 * ((x[0] - 1)**2 + (x[1] + 1)**2))
    else:
        gaussian_well = -0.5 * np.exp(-0.3 * (x[0] - 1)**2)  if dim > 0 else -0.5 * np.exp(-0.3)


    # Modulated Sinusoidal Term
    if dim >= 1:
        modulated_sinusoid = 0.2 * np.sin(3 * np.pi * x[0]) * x[0]
    else:
        modulated_sinusoid = 0.0

    # Inverse Squared Distance
    if dim >= 2:
        inverse_squared_distance = -0.1 / (1 + 5*((x[0] + 0.5)**2 + (x[1] - 0.5)**2))*x[1]
    else:
      inverse_squared_distance = -0.1 / (1 + 5*(x[0] + 0.5)**2) if dim > 0 else -0.1


    return hyperbolic_paraboloid + gaussian_well + modulated_sinusoid + inverse_squared_distance

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function designed to test global optimization algorithms.
    """
    dim = x.shape[0]

    # Skewed quadratic surface
    Q = np.array([[1.0, 0.2], [0.2, 0.5]]) if dim == 2 else np.eye(dim)
    skewed_quadratic = 0.5 * x @ Q @ x * 0.7

    # Shifted exponential
    if dim >= 1:
        exponential_term =  0.4*np.exp(-abs(x[0]-2))
    else:
        exponential_term =  0.4*np.exp(-2)

    # Cosine term scaled by x[1]
    if dim >= 2:
        cosine_term = 0.2 * np.cos(5 * x[0]) * x[1]
    else:
        cosine_term = 0.0

    # Inverse Sine term
    if dim >= 1:
        inverse_sine = -0.3 / (1 + np.sin(x[0])**2)
    else:
        inverse_sine = -0.3

    # Hyperbolic tangent sigmoid modulated by x[0]
    if dim >= 1:
        tanh_term = 0.1 * np.tanh(x[0]) * (1 + 0.5*x[0])
    else:
        tanh_term=0.0

    return skewed_quadratic + exponential_term + cosine_term + inverse_sine + tanh_term

import numpy as np
from scipy.special import erfc

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function designed to test global optimization algorithms.
    """
    dim = x.shape[0]

    # Skewed quadratic surface
    Q = np.array([[1.0, 0.2], [0.2, 0.5]]) if dim == 2 else np.eye(dim)
    skewed_quadratic = 0.5 * x @ Q @ x * 0.8

    # Logarithmic scaling of the quadratic term
    if dim >=1:
        skewed_quadratic *= np.log(np.abs(x[0]) + 1) # shifts lin adj_r2 down
    else:
        skewed_quadratic *= np.log(1)

    # Rotated Gaussian peak
    if dim >= 2:
        rotation_matrix = np.array([[0.707, -0.707], [0.707, 0.707]])
        x_rotated = x[:2] @ rotation_matrix
        gaussian_peak = -0.6 * np.exp(-0.5 * np.sum((x_rotated - [1, -1])**2))
    else:
        gaussian_peak = -0.6 * np.exp(-0.5 * (x[0] - 1)**2) if dim > 0 else -0.6 * np.exp(-0.5)


    # Cubic term with sine modulation
    if dim >= 1:
        cubic_term = 0.1 * x[0]**3 * np.sin(2 * np.pi * x[0])
    else:
        cubic_term = 0.0

    # Inverse quadratic term modulated by x[1]
    if dim >= 2:
        inverse_quadratic = -0.2 / (1 + (x[0]**2 / (1 + x[1]**2)))
    else:
        inverse_quadratic = -0.2 / (1 + x[0]**2) if dim > 0 else -0.2

    # Complementary error function influence on x[0]
    if dim >= 1:
        erfc_term = 0.3 * erfc(x[0])
    else:
        erfc_term = 0.3 * erfc(0)

    # Rational function modulated by x[1] plus squared exponential
    if dim >= 2:
        rational_term = 0.1 * (x[1] / (1 + x[0]**2)) -0.1 * np.exp(-x[0]**2 - x[1]**2)
    else:
         rational_term = 0.0

    return skewed_quadratic + gaussian_peak + cubic_term + inverse_quadratic + erfc_term + rational_term

